/**
 * og-fonts.js · Tipografías de la imagen OG (las mismas del sitio)
 * ─────────────────────────────────────────────────────────────────────────
 * Recortadas a los caracteres que usa og-image.js, embebidas como base64 y
 * decodificadas una vez al cargar el módulo. Fuente: github.com/google/fonts
 * (OFL), instancia estática de la variable con fontTools.
 *
 * Si og-image.js necesita un carácter que no está, hay que regenerarlas:
 *   python3 -m fontTools.subset <fuente>.ttf --text="…" --layout-features=kern
 * ─────────────────────────────────────────────────────────────────────────
 */

function decode(b64) {
  const bin = atob(b64);
  const buf = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
  return buf;
}

